1	"use server";
2	
3	import { redirect } from "next/navigation";
4	import { revalidatePath } from "next/cache";
5	import { getUser, getProfile, requireRole } from "@/lib/auth";
6	import { createClient } from "@/lib/supabase/server";
7	import { createAdminClient } from "@/lib/supabase/admin";
8	import { getCalls } from "@/lib/integrations/calls";
9	import { getPayments } from "@/lib/integrations/payments";
10	import { computeSessionAccounting, roundHalfUp } from "@/lib/pricing";
11	import { type BlockMinutes } from "@/lib/pricing";
12	import { reviewSchema, type ReviewInput } from "@/lib/validation/schemas";
13	
14	async function loadBookingForParty(bookingId: string) {
15	  const user = await getUser();
16	  if (!user) redirect("/signin");
17	  const supabase = await createClient();
18	  const { data: booking } = await supabase
19	    .from("bookings")
20	    .select("*")
21	    .eq("id", bookingId)
22	    .maybeSingle();
23	  // RLS already restricts to a party; double-check defensively.
24	  if (
25	    !booking ||
26	    (booking.customer_id !== user.id && booking.provider_id !== user.id)
27	  ) {
28	    return null;
29	  }
30	  return booking;
31	}
32	
33	export interface StartSessionResult {
34	  sessionId?: string;
35	  error?: string;
36	}
37	
38	/**
39	 * Start (or re-join) the mock call for a booking. Idempotent: returns the
40	 * existing session if one already exists. Creates the call session via the
41	 * calls adapter and the sessions row via the service-role client.
42	 */
43	export async function startSession(
44	  bookingId: string,
45	): Promise<StartSessionResult> {
46	  const booking = await loadBookingForParty(bookingId);
47	  if (!booking) return { error: "This session isn't available." };
48	
49	  // A suspended customer cannot start a call (safety: protects providers).
50	  const profile = await getProfile();
51	  if (profile?.id === booking.customer_id && profile.is_suspended) {
52	    return { error: "Your account is paused. Please contact support." };
53	  }
54	
55	  const supabase = await createClient();
56	  const { data: existing } = await supabase
57	    .from("sessions")
58	    .select("id")
59	    .eq("booking_id", bookingId)
60	    .maybeSingle();
61	  if (existing) return { sessionId: existing.id };
62	
63	  const calls = getCalls();
64	  const { callSessionRef } = await calls.createSession({
65	    bookingId,
66	    providerId: booking.provider_id,
67	    customerId: booking.customer_id,
68	    maxMinutes: booking.block_minutes + 15,
69	  });
70	
71	  const admin = createAdminClient();
72	  const { data: session, error } = await admin
73	    .from("sessions")
74	    .insert({
75	      booking_id: bookingId,
76	      provider_id: booking.provider_id,
77	      customer_id: booking.customer_id,
78	      call_session_ref: callSessionRef,
79	      started_at: new Date().toISOString(),
80	      block_minutes: booking.block_minutes,
81	      status: "in_progress",
82	    })
83	    .select("id")
84	    .single();
85	  if (error || !session) return { error: "We couldn't start the call." };
86	
87	  await supabase
88	    .from("bookings")
89	    .update({ status: "in_progress" })
90	    .eq("id", bookingId);
91	
92	  return { sessionId: session.id };
93	}
94	
95	export interface EndSessionResult {
96	  ok?: true;
97	  error?: string;
98	}
99	
100	/**
101	 * End the mock call. The client's count-up timer is the source of truth for
102	 * elapsed seconds (mock mode). Computes the final accounting (block + overage +
103	 * commission), captures the hold, and marks the session + booking completed.
104	 * Idempotent: a session already completed is left as-is.
105	 */
106	export async function endSession(
107	  bookingId: string,
108	  elapsedSeconds: number,
109	): Promise<EndSessionResult> {
110	  const booking = await loadBookingForParty(bookingId);
111	  if (!booking) return { error: "This session isn't available." };
112	
113	  const supabase = await createClient();
114	  const { data: session } = await supabase
115	    .from("sessions")
116	    .select("*")
117	    .eq("booking_id", bookingId)
118	    .maybeSingle();
119	  if (!session) return { error: "This session isn't available." };
120	  if (session.status === "completed") return { ok: true };
121	
122	  const elapsed = Math.max(0, Math.floor(elapsedSeconds || 0));
123	  const accounting = computeSessionAccounting({
124	    priceBlockCents: booking.price_block_cents,
125	    overagePerMinCents: booking.overage_per_min_cents,
126	    elapsedSeconds: elapsed,
127	    blockMinutes: booking.block_minutes as BlockMinutes,
128	  });
129	
130	  const calls = getCalls();
131	  if (session.call_session_ref) {
132	    await calls.endSession({ callSessionRef: session.call_session_ref });
133	  }
134	
135	  const payments = getPayments();
136	  if (booking.payment_ref) {
137	    await payments.capture({
138	      paymentRef: booking.payment_ref,
139	      amountCents: accounting.totalCents,
140	    });
141	  }
142	
143	  const admin = createAdminClient();
144	  const { error } = await admin
145	    .from("sessions")
146	    .update({
147	      ended_at: new Date().toISOString(),
148	      elapsed_seconds: elapsed,
149	      overage_minutes: accounting.overageMinutes,
150	      total_price_cents: accounting.totalCents,
151	      commission_cents: accounting.commissionCents,
152	      provider_earnings_cents: accounting.providerEarningsCents,
153	      status: "completed",
154	    })
155	    .eq("id", session.id);
156	  if (error) return { error: "We couldn't finish the call." };
157	
158	  await supabase
159	    .from("bookings")
160	    .update({ status: "completed" })
161	    .eq("id", bookingId);
162	
163	  return { ok: true };
164	}
165	
166	export interface ReviewResult {
167	  ok?: true;
168	  error?: string;
169	}
170	
171	/**
172	 * Submit a post-session review + optional tip. Inserts the review (RLS:
173	 * customer owns it), recomputes the provider's rating, and revalidates. Tips
174	 * carry no commission and are aggregated into payouts from the reviews table
175	 * (so they're not double-counted on the session row).
176	 */
177	export async function submitReview(input: ReviewInput): Promise<ReviewResult> {
178	  const profile = await requireRole("customer");
179	  const parsed = reviewSchema.safeParse(input);
180	  if (!parsed.success) return { error: "Please choose a rating." };
181	  const d = parsed.data;
182	
183	  const supabase = await createClient();
184	
185	  // The session must be the caller's own, completed.
186	  const { data: session } = await supabase
187	    .from("sessions")
188	    .select("id, customer_id, provider_id, status")
189	    .eq("id", d.sessionId)
190	    .maybeSingle();
191	  if (!session || session.customer_id !== profile.id) {
192	    return { error: "This session isn't available." };
193	  }
194	
195	  // One review per session.
196	  const { data: existing } = await supabase
197	    .from("reviews")
198	    .select("id")
199	    .eq("session_id", d.sessionId)
200	    .maybeSingle();
201	  if (existing) return { ok: true };
202	
203	  const { error: insErr } = await supabase.from("reviews").insert({
204	    session_id: d.sessionId,
205	    customer_id: profile.id,
206	    provider_id: session.provider_id,
207	    rating: d.rating,
208	    comment: d.comment ?? null,
209	    tip_cents: d.tipCents,
210	  });
211	  if (insErr) return { error: "We couldn't save your review." };
212	
213	  // Recompute the provider's rating (privileged column → service role).
214	  const admin = createAdminClient();
215	  const { data: ratings } = await admin
216	    .from("reviews")
217	    .select("rating")
218	    .eq("provider_id", session.provider_id);
219	  const count = ratings?.length ?? 0;
220	  const sum = (ratings ?? []).reduce((acc, r) => acc + r.rating, 0);
221	  const avg = count > 0 ? roundHalfUp((sum / count) * 100) / 100 : 0;
222	  await admin
223	    .from("providers")
224	    .update({ rating_avg: avg, rating_count: count })
225	    .eq("id", session.provider_id);
226	
227	  revalidatePath(`/session/${session.id}/summary`);
228	  revalidatePath("/provider/dashboard");
229	  return { ok: true };
230	}
